//! THE SNAPSHOT RUNNER: a package's cases, held and written.
//!
//! A case is `<function>/<case>.trig`, the store before, and `<case>.diff`, what the function changes; what the
//! function must leave is the case with the diff applied, compared quad by quad, blank nodes by their shape, and a
//! mismatch reported graph by graph.
//!
//! `UPDATE_SNAPSHOTS=1 cargo test` REWRITES each diff from what the function left: a behaviour change is a diff
//! regenerated by a flag and reviewed by eyes. What is written is the case's text with every graph rendered one
//! statement a line and sorted, so adding a statement adds a line and a graph that did not change is no hunk.

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::{Arc, LazyLock};

use oxigraph::model::dataset::CanonicalizationAlgorithm;
use oxigraph::model::{BlankNodeRef, Dataset, Graph, LiteralRef, NamedOrBlankNodeRef, TermRef};
use oxsdatatypes::DateTime;
use regex::Regex;
use similar::TextDiff;

use crate::namespaces::Namespaces;
use crate::ontology::ONTOLOGY;
use crate::store::{Store, Within};

/// Where a case's default graph goes: the world's graph, as the Python stand-in names it.
pub const WORLD: &str = "http://example.org/test#world";
/// The agent a case is about, and its id.
pub const ME: &str = "http://example.org/test#keeper";
pub const AGENT: &str = "keeper";

const REGENERATE: &str = "UPDATE_SNAPSHOTS=1 cargo test";

static HUNK: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r"^@@ -(\d+)(?:,\d+)? \+\d+(?:,\d+)? @@").expect("a valid pattern"));

/// The one instant a case stands at: no case reads a clock.
pub fn now() -> DateTime {
    crate::clock::instant("2026-01-01T12:00:00Z").expect("a valid instant")
}

/// The agent's tree, whose ontologies say what a text may spell.
pub fn tree() -> &'static Path {
    Path::new(env!("CARGO_MANIFEST_DIR"))
}

/// The namespaces of the tree, read once a test process.
pub fn namespaces() -> Arc<Namespaces> {
    static FOUND: LazyLock<Arc<Namespaces>> =
        LazyLock::new(|| Arc::new(Namespaces::of_tree(tree()).expect("the tree's prefixes agree")));
    FOUND.clone()
}

/// The cases of one directory, sorted: `<case>.trig`, never a `<case>.actual.trig`.
pub fn cases_in(directory: &Path) -> Vec<PathBuf> {
    let mut out: Vec<PathBuf> = fs::read_dir(directory)
        .unwrap_or_else(|e| panic!("{}: {e}", directory.display()))
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| p.extension().is_some_and(|e| e == "trig"))
        .filter(|p| p.file_stem().and_then(|s| s.to_str()).is_some_and(|s| !s.contains('.')))
        .collect();
    out.sort();
    out
}

/// The store a case describes, its rows closed: refused where it names no catalogue or types no vocabulary graph,
/// since a case says what its graphs are and what it is loaded with.
pub fn stand_in(case: &Path) -> Store {
    stand_in_with(case, "")
}

/// The store a case describes with `more` TriG after it, in the case's prefixes — as the Python stand-in takes a
/// case's text with a test's additions.
pub fn stand_in_with(case: &Path, more: &str) -> Store {
    let store = Store::new(namespaces()).expect("an empty store");
    store
        .put_trig(WORLD, &format!("{}\n{more}", read(case)))
        .unwrap_or_else(|e| panic!("{}: {e}", name(case)));
    assert!(
        store.catalogue().expect("one catalogue").is_some(),
        "{} names no graph that describes itself as the catalogue",
        name(case)
    );
    assert!(
        !store
            .graphs_of(&[ONTOLOGY], &Within::default())
            .expect("graphs by kind")
            .is_empty(),
        "{} types no graph as the vocabulary's",
        name(case)
    );
    store.close_catalogue().expect("the rows closed");
    store
}

/// The lines that say something: a comment is never what a case is held to.
pub fn without_comments(text: &str) -> String {
    text.split_inclusive('\n')
        .filter(|l| !l.trim_start().starts_with('#'))
        .collect()
}

/// `case` with `diff` applied, strictly, by line number: a hunk that does not land where it says is a stale
/// diff, refused rather than guessed at.
pub fn patched(case: &str, diff: &str) -> String {
    let stripped = without_comments(case);
    let lines: Vec<&str> = stripped.split_inclusive('\n').collect();
    let mut out: Vec<&str> = Vec::new();
    let (mut at, mut started) = (0usize, false);
    for line in diff.split_inclusive('\n') {
        if let Some(head) = HUNK.captures(line) {
            started = true;
            let start: usize = head[1].parse::<usize>().expect("a line number") - 1;
            out.extend(&lines[at..start]);
            at = start;
            continue;
        }
        if !started {
            continue;
        }
        if let Some(added) = line.strip_prefix('+') {
            out.push(added);
        } else if let Some(said) = line.strip_prefix('-').or_else(|| line.strip_prefix(' ')) {
            assert_eq!(lines.get(at).copied(), Some(said), "stale diff at line {}", at + 1);
            if line.starts_with(' ') {
                out.push(lines[at]);
            }
            at += 1;
        }
    }
    out.extend(&lines[at..]);
    out.concat()
}

/// Hold what `function` left in `store` to `<case>.diff` beside the case: every quad of every named graph, blank
/// nodes by their shape. A mismatch names the quads left that the diff does not say and the quads it says that
/// were not left.
pub fn held_to_diff(case: &Path, store: &Store, function: &str) {
    let path = case.with_extension("diff");
    if std::env::var_os("UPDATE_SNAPSHOTS").is_some() {
        fs::write(&path, regenerated(&read(case), store)).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    }
    assert!(
        path.exists(),
        "{} has no diff: run `{REGENERATE}` and review {}",
        name(case),
        name(&path)
    );
    let expected = Store::new(namespaces()).expect("an empty store");
    expected
        .put_trig(WORLD, &patched(&read(case), &read(&path)))
        .unwrap_or_else(|e| panic!("{} with its diff: {e}", name(case)));
    if dataset(store) == dataset(&expected) {
        return;
    }
    panic!(
        "{}: the store `{function}` left differs from case + {}\n{}  if the change is on purpose, `{REGENERATE}` \
         rewrites the diff, to be reviewed",
        name(case),
        name(&path),
        by_graph(store, &expected),
    );
}

/// The diff that turns `case` into the store `store` holds, comments left out of both.
fn regenerated(case: &str, store: &Store) -> String {
    let (before, after) = (without_comments(case), without_comments(&trig_of(case, store)));
    TextDiff::from_lines(&before, &after)
        .unified_diff()
        .context_radius(3)
        .header("case", "expected")
        .to_string()
}

static PREFIX: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"(?m)^@prefix ([\w-]*): <([^>]*)> \.").unwrap());
//  A block is one line holding its closing brace, or lines up to a line that is one: never a one-line block that runs
//  on to the next block's brace.
static BLOCK: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new(r"(?ms)(?:^#[^\n]*\n)*^GRAPH (\S+) \{(?:[^\n]*\}[ \t]*\n|[ \t]*\n(?:.*?^\}\n)?)\n*").unwrap()
});
static BARE: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"^(?:[-+]?\d+(?:\.\d+)?|true|false)$").unwrap());
static LOCAL: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"^[\w.\-]*$").unwrap());

const RDF_TYPE: &str = "http://www.w3.org/1999/02/22-rdf-syntax-ns#type";
const RDF_FIRST: &str = "http://www.w3.org/1999/02/22-rdf-syntax-ns#first";
const RDF_REST: &str = "http://www.w3.org/1999/02/22-rdf-syntax-ns#rest";
const RDF_NIL: &str = "http://www.w3.org/1999/02/22-rdf-syntax-ns#nil";
const XSD: &str = "http://www.w3.org/2001/XMLSchema#";

/// The store after a function ran, as the case's text with every graph rendered in place: its preamble and its
/// graphs' order and spacing kept, a graph it no longer holds left out, a graph it did not name written last.
fn trig_of(case: &str, store: &Store) -> String {
    let mut prefixes: Vec<(String, String)> = PREFIX
        .captures_iter(case)
        .map(|c| (c[1].to_string(), c[2].to_string()))
        .collect();
    let by_prefix: BTreeMap<String, String> = prefixes.iter().cloned().collect();
    prefixes.sort_by_key(|(_, namespace)| std::cmp::Reverse(namespace.len()));
    let after: BTreeSet<String> = store.graph_names().expect("the graphs").into_iter().collect();
    let blocks: Vec<_> = BLOCK.captures_iter(case).collect();
    assert!(!blocks.is_empty(), "a case holds no GRAPH block");
    let mut out = case[..blocks[0].get(0).unwrap().start()].to_string();
    let mut named = BTreeSet::new();
    for block in &blocks {
        let text = block.get(0).unwrap().as_str();
        let graph = match block[1].strip_prefix('<') {
            Some(rest) => rest.trim_end_matches('>').to_string(),
            None => {
                let (prefix, local) = block[1].split_once(':').expect("a prefixed graph name");
                format!("{}{local}", by_prefix[prefix])
            }
        };
        let spacing = &text[text.trim_end_matches('\n').len()..];
        if after.contains(&graph) {
            out += render(&graph, store, &prefixes).trim_end_matches('\n');
        }
        out += spacing;
        named.insert(graph);
    }
    let written: Vec<_> = after.difference(&named).map(|g| render(g, store, &prefixes)).collect();
    if !written.is_empty() {
        out += "\n\n";
        out += &written.join("\n");
    }
    out
}

/// One graph as a TriG block, one line per statement and sorted, so a change of one statement is a diff of one line;
/// a blank node used once inlined where it is used and an RDF list as `( … )`, since a shape is a tree of them.
fn render(graph: &str, store: &Store, prefixes: &[(String, String)]) -> String {
    let mut canonical = Graph::new();
    for triple in store.triples(graph).expect("a graph's triples") {
        canonical.insert(&triple);
    }
    canonical.canonicalize(CanonicalizationAlgorithm::Unstable);
    let labels: BTreeMap<String, String> = canonical
        .iter()
        .flat_map(|t| {
            let subject = match t.subject {
                NamedOrBlankNodeRef::BlankNode(b) => Some(b.as_str().to_string()),
                _ => None,
            };
            let object = match t.object {
                TermRef::BlankNode(b) => Some(b.as_str().to_string()),
                _ => None,
            };
            [subject, object]
        })
        .flatten()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .enumerate()
        .map(|(n, label)| (label, format!("b{}", n + 1)))
        .collect();
    let mut uses: BTreeMap<String, usize> = BTreeMap::new();
    for t in canonical.iter() {
        if let TermRef::BlankNode(b) = t.object {
            *uses.entry(b.as_str().to_string()).or_default() += 1;
        }
    }
    let view = View {
        graph: &canonical,
        prefixes,
        labels: &labels,
        uses: &uses,
    };
    let mut lines: Vec<String> = canonical
        .iter()
        .filter(|t| !matches!(t.subject, NamedOrBlankNodeRef::BlankNode(b) if view.inlined(b.as_str())))
        .map(|t| {
            let subject = match t.subject {
                NamedOrBlankNodeRef::NamedNode(n) => view.iri(n.as_str()),
                NamedOrBlankNodeRef::BlankNode(b) => format!("_:{}", labels[b.as_str()]),
            };
            format!(
                "  {subject} {} {} .",
                view.iri(t.predicate.as_str()),
                view.term(t.object)
            )
        })
        .collect();
    lines.sort();
    format!(
        "GRAPH {} {{\n{}{}}}\n",
        view.iri(graph),
        lines.join("\n"),
        if lines.is_empty() { "" } else { "\n" }
    )
}

struct View<'a> {
    graph: &'a Graph,
    prefixes: &'a [(String, String)],
    labels: &'a BTreeMap<String, String>,
    uses: &'a BTreeMap<String, usize>,
}

impl View<'_> {
    fn inlined(&self, node: &str) -> bool {
        self.uses.get(node) == Some(&1)
    }

    fn iri(&self, iri: &str) -> String {
        if iri == RDF_TYPE {
            return "a".to_string();
        }
        match self.abbreviated(iri) {
            Some(short) if !iri.ends_with('.') => short,
            _ => format!("<{iri}>"),
        }
    }

    fn abbreviated(&self, iri: &str) -> Option<String> {
        self.prefixes.iter().find_map(|(prefix, namespace)| {
            let local = iri.strip_prefix(namespace.as_str())?;
            LOCAL.is_match(local).then(|| format!("{prefix}:{local}"))
        })
    }

    fn literal(&self, literal: LiteralRef<'_>) -> String {
        let value = literal.value();
        let datatype = literal.datatype().as_str();
        if let Some(kind) = datatype.strip_prefix(XSD)
            && matches!(kind, "integer" | "decimal" | "boolean")
            && BARE.is_match(value)
        {
            //  A decimal keeps its point: Turtle's bare forms are typed by their spelling, and `1` is an integer.
            return if kind == "decimal" && !value.contains('.') {
                format!("{value}.0")
            } else {
                value.to_string()
            };
        }
        let quoted = quoted(value);
        if let Some(language) = literal.language() {
            return format!("{quoted}@{language}");
        }
        if datatype == "http://www.w3.org/2001/XMLSchema#string" {
            return quoted;
        }
        match self.abbreviated(datatype) {
            Some(short) => format!("{quoted}^^{short}"),
            None => format!("{quoted}^^<{datatype}>"),
        }
    }

    fn term(&self, term: TermRef<'_>) -> String {
        match term {
            TermRef::NamedNode(n) => self.iri(n.as_str()),
            TermRef::Literal(l) => self.literal(l),
            TermRef::BlankNode(b) if self.inlined(b.as_str()) => self.inline(b),
            TermRef::BlankNode(b) => format!("_:{}", self.labels[b.as_str()]),
            #[allow(unreachable_patterns)]
            other => other.to_string(),
        }
    }

    fn inline(&self, node: BlankNodeRef<'_>) -> String {
        let pairs: Vec<(String, TermRef<'_>)> = self
            .graph
            .triples_for_subject(node)
            .map(|t| (t.predicate.as_str().to_string(), t.object))
            .collect();
        let predicates: BTreeSet<&str> = pairs.iter().map(|(p, _)| p.as_str()).collect();
        if predicates == BTreeSet::from([RDF_FIRST, RDF_REST]) {
            return format!("( {} )", self.list(&pairs).join(" "));
        }
        let mut said: Vec<(String, String)> = pairs.iter().map(|(p, o)| (self.iri(p), self.term(*o))).collect();
        said.sort();
        let body: Vec<String> = said.into_iter().map(|(p, o)| format!("{p} {o}")).collect();
        format!("[ {} ]", body.join(" ; "))
    }

    fn list(&self, pairs: &[(String, TermRef<'_>)]) -> Vec<String> {
        let at = |predicate: &str| {
            pairs
                .iter()
                .find(|(p, _)| p == predicate)
                .map(|(_, o)| *o)
                .expect("a list cell")
        };
        let mut items = vec![self.term(at(RDF_FIRST))];
        match at(RDF_REST) {
            TermRef::NamedNode(n) if n.as_str() == RDF_NIL => {}
            TermRef::BlankNode(next) => {
                let rest: Vec<(String, TermRef<'_>)> = self
                    .graph
                    .triples_for_subject(next)
                    .map(|t| (t.predicate.as_str().to_string(), t.object))
                    .collect();
                items.extend(self.list(&rest));
            }
            other => panic!("a list whose rest is {other}"),
        }
        items
    }
}

/// A string as Turtle says it: three quotes where it holds a newline, one line otherwise.
fn quoted(value: &str) -> String {
    if value.contains('\n') {
        let mut encoded = value.replace('\\', "\\\\");
        encoded = encoded.replace("\"\"\"", "\\\"\\\"\\\"");
        if encoded.ends_with('"') && !encoded.ends_with("\\\"") {
            encoded.pop();
            encoded += "\\\"";
        }
        return format!("\"\"\"{}\"\"\"", encoded.replace('\r', "\\r"));
    }
    format!(
        "\"{}\"",
        value.replace('\\', "\\\\").replace('"', "\\\"").replace('\r', "\\r")
    )
}

/// What every suite asks of its directory: at least `least` cases are read, and no diff is left whose case was
/// deleted or renamed.
pub fn all_read(directory: &Path, least: usize) {
    let found = cases_in(directory);
    assert!(
        found.len() >= least,
        "{}: {} case(s), fewer than {least}",
        directory.display(),
        found.len()
    );
    let orphans = orphans_in(directory);
    assert!(
        orphans.is_empty(),
        "{}: orphaned diffs {orphans:?}",
        directory.display()
    );
}

/// Diffs whose case was deleted or renamed.
pub fn orphans_in(directory: &Path) -> Vec<String> {
    let mut out: Vec<String> = fs::read_dir(directory)
        .expect("a directory")
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| p.extension().is_some_and(|e| e == "diff") && !p.with_extension("trig").exists())
        .map(|p| name(&p))
        .collect();
    out.sort();
    out
}

/// Every quad of every named graph — the default graph is nothing a case holds a function to — canonical as one
/// dataset, so a blank node two graphs share is held to being shared.
fn dataset(store: &Store) -> Dataset {
    let mut out = Dataset::new();
    for graph in store.graph_names().expect("the graphs") {
        for quad in store.quads(&graph).expect("a graph's quads") {
            out.insert(&quad);
        }
    }
    out.canonicalize(CanonicalizationAlgorithm::Unstable);
    out
}

/// One graph's triples, canonical alone: a graph that differs is reported by itself, and a blank node relabelled
/// in it relabels nothing in another.
fn triples(store: &Store, graph: &str) -> BTreeSet<String> {
    let mut out = Graph::new();
    for triple in store.triples(graph).expect("a graph's triples") {
        out.insert(&triple);
    }
    out.canonicalize(CanonicalizationAlgorithm::Unstable);
    out.iter().map(|t| t.to_string()).collect()
}

/// The report of two stores that differ: per graph either holds, what it has that the other lacks, one triple a
/// line. Where every graph agrees alone, what differs is which blank nodes the graphs share.
fn by_graph(left: &Store, expected: &Store) -> String {
    let mut graphs: BTreeSet<String> = left.graph_names().expect("the graphs").into_iter().collect();
    graphs.extend(expected.graph_names().expect("the graphs"));
    let mut out = String::new();
    for graph in &graphs {
        let (l, e) = (triples(left, graph), triples(expected, graph));
        if l == e {
            continue;
        }
        out += &format!("  <{graph}>\n");
        for t in l.difference(&e) {
            out += &format!("    left, unexpected:         {t}\n");
        }
        for t in e.difference(&l) {
            out += &format!("    the diff says, missing:  {t}\n");
        }
    }
    if out.is_empty() {
        out += "  every graph agrees alone: the blank nodes two graphs share differ\n";
    }
    out
}

fn read(path: &Path) -> String {
    fs::read_to_string(path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

fn name(path: &Path) -> String {
    path.file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_diff_applies_by_line_number_and_comments_are_no_lines() {
        let case = "# a header\n@prefix : <urn:> .\nGRAPH :g {\n  :a :b :c .\n}\n";
        let diff =
            "--- case\n+++ expected\n@@ -1,3 +1,4 @@\n @prefix : <urn:> .\n GRAPH :g {\n   :a :b :c .\n+  :a :b :d .\n";
        assert_eq!(
            patched(case, diff),
            "@prefix : <urn:> .\nGRAPH :g {\n  :a :b :c .\n  :a :b :d .\n}\n"
        );
    }

    fn store_of(trig: &str) -> Store {
        let store = Store::new(namespaces()).expect("an empty store");
        store.put_trig(WORLD, trig).expect("the case");
        store
    }

    #[test]
    fn a_report_names_the_graph_that_differs_and_no_other() {
        let left = store_of("@prefix : <urn:> .\nGRAPH :g { :a :b [ :c 1 ] }\nGRAPH :h { :a :b :c }\n");
        let expected = store_of("@prefix : <urn:> .\nGRAPH :g { :a :b [ :c 1 ] }\nGRAPH :h { :a :b :d }\n");
        assert_ne!(dataset(&left), dataset(&expected));
        let report = by_graph(&left, &expected);
        assert!(!report.contains("<urn:g>"), "{report}");
        assert!(report.contains("<urn:h>"), "{report}");
        assert!(
            report.contains("left, unexpected:         <urn:a> <urn:b> <urn:c>"),
            "{report}"
        );
        assert!(
            report.contains("the diff says, missing:  <urn:a> <urn:b> <urn:d>"),
            "{report}"
        );
    }

    #[test]
    fn a_blank_node_two_graphs_share_is_held_to_being_shared() {
        let left = store_of("@prefix : <urn:> .\nGRAPH :g { :a :b _:x }\nGRAPH :h { _:x :c 1 }\n");
        let expected = store_of("@prefix : <urn:> .\nGRAPH :g { :a :b _:x }\nGRAPH :h { _:y :c 1 }\n");
        assert_ne!(dataset(&left), dataset(&expected));
        assert!(by_graph(&left, &expected).contains("the blank nodes two graphs share differ"));
    }

    #[test]
    fn a_diff_written_and_applied_to_its_case_is_the_store_left() {
        let case =
            "@prefix : <http://example.org/test#> .\n\nGRAPH :a {\n  :x :p 1 .\n}\n\nGRAPH :gone {\n  :x :p 2 .\n}\n";
        let left = store_of(
            "@prefix : <http://example.org/test#> .\n@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\n\
             GRAPH :a { :x :p 1 ; :q [ :r ( 1 2 ) ; :s \"two\\nlines\" ] ; :t \"1.0\"^^xsd:decimal . }\n\
             GRAPH :new { _:b :p _:b . :y :p _:b . :z :p \"a\\\"b\"@en . }\n",
        );
        let expected = store_of(&patched(case, &regenerated(case, &left)));
        assert_eq!(dataset(&left), dataset(&expected), "{}", by_graph(&left, &expected));
    }

    #[test]
    #[should_panic(expected = "stale diff at line 2")]
    fn a_hunk_that_does_not_land_where_it_says_is_refused() {
        patched("a\nb\n", "@@ -1,2 +1,2 @@\n a\n-c\n+d\n");
    }
}
